// ---------- ui.js ----------
// 共用介面元件（設計系統）：window.UI
// 風格：細線分隔的數據表（ledger）取代盒狀卡片；大數字用 font-display（Barlow Condensed），
// 標籤一律「中文 + 小字 NBA 原文」。Tailwind class 必須完整寫在這裡（CLI 掃不到字串拼接）。
//   StatCell  單一指標格（數值三態：真的 0 照常顯示／無資料「—」／不適用「—」+ tooltip）
//   Ledger    StatCell 的容器（外框上/左線 + 每格右/下線，空位不畫線）
//   PctBar    百分位色階條（紅 → 月光銀 → 綠，中線 = 聯盟中位）；只給「真的有 percentile」的資料用
//   DataTable 可排序表格（Synergy 式：數字右對齊等寬、首欄在手機橫捲時固定且限寬換行，避免長名稱蓋住數字）
window.UI = (function () {
    // 「切入次數 (Drives)」→ ['切入次數', 'Drives']；沒有括號就整串當中文
    const splitTitle = (title) => {
        const m = String(title || '').match(/^(.*?)\s*\(([^()]*)\)\s*$/);
        return m ? [m[1], m[2]] : [String(title || ''), null];
    };

    // 0–100 → 紅(#EF4444) / 月光銀(#C4CED2) / 綠(#12A150) 線性內插
    const RED = [239, 68, 68], SILVER = [196, 206, 210], GREEN = [18, 161, 80];
    const mix = (a, b, t) => a.map((v, i) => Math.round(v + (b[i] - v) * t));
    const pctColor = (p) => {
        const v = Math.max(0, Math.min(100, p)) / 100;
        const c = v < 0.5 ? mix(RED, SILVER, v / 0.5) : mix(SILVER, GREEN, (v - 0.5) / 0.5);
        return `rgb(${c[0]}, ${c[1]}, ${c[2]})`;
    };

    const isBlank = (v) => v == null || v === '';

    // 漲跌：betterIsLarger=false 時（失誤、對手命中率…）下降才是好
    const Delta = ({ value, prevValue, unit = '', betterIsLarger = true, digits = 1 }) => {
        if (isBlank(value) || isBlank(prevValue)) return null;
        const d = +(Number(value) - Number(prevValue)).toFixed(digits);
        if (!d) return null;
        const good = (d > 0) === betterIsLarger;
        return (
            <span className={`font-mono text-[10px] tabular-nums whitespace-nowrap ${good ? 'text-[#12A150]' : 'text-[#EF4444]'}`}>
                {d > 0 ? '▲' : '▼'} {Math.abs(d)}{unit}
            </span>
        );
    };

    const PctBar = ({ value, label = 'PR' }) => {
        if (typeof value !== 'number') return null;
        const v = Math.max(0, Math.min(100, value));
        const color = pctColor(v);
        return (
            <div className="mt-2.5">
                <div className="flex justify-between font-mono text-[10px] text-slate-500" title="聯盟百分位（Percentile，0–100，越高越好；中線為聯盟中位數）">
                    <span>{label}</span>
                    <span className="tabular-nums" style={{ color }}>{v.toFixed(1)}</span>
                </div>
                <div className="relative h-[3px] mt-1 bg-white/[0.08]">
                    <div className="absolute inset-y-0 left-0" style={{ width: v + '%', background: color }}></div>
                    <div className="absolute -top-[2px] left-1/2 h-[7px] w-px bg-slate-400/50" title="聯盟中位數"></div>
                </div>
            </div>
        );
    };

    const StatCell = ({ label, en, value, unit = '', prevValue, betterIsLarger = true, naReason = null, pct = null, pctLabel }) => {
        const isNA = naReason && isBlank(value);
        const missing = isBlank(value);
        return (
            <div className="border-r border-b border-white/[0.08] px-3 pt-2.5 pb-3 min-w-0">
                <div className="text-[11px] leading-tight text-slate-300 truncate" title={label}>{label}</div>
                {en && <div className="font-mono text-[10px] leading-tight text-slate-500 truncate" title={en}>{en}</div>}
                <div className="mt-2 flex items-baseline gap-1.5 min-w-0">
                    {isNA ? (
                        <span className="font-display text-[26px] font-semibold leading-none text-slate-600 cursor-help" title={naReason}>—</span>
                    ) : missing ? (
                        <span className="font-display text-[26px] font-semibold leading-none text-slate-600" title="此項無資料">—</span>
                    ) : (
                        <span className="font-display text-[26px] font-semibold leading-none tabular-nums text-slate-50">
                            {value}{unit && <span className="ml-0.5 text-[15px] font-medium text-slate-400">{unit}</span>}
                        </span>
                    )}
                    {!isNA && !missing && <span className="ml-auto"><Delta value={value} prevValue={prevValue} unit={unit} betterIsLarger={betterIsLarger} /></span>}
                </div>
                {pct != null && <PctBar value={pct} label={pctLabel} />}
            </div>
        );
    };

    // cols：完整的 grid-cols class（例 'grid-cols-2 sm:grid-cols-4'），由呼叫端依指標數決定
    const Ledger = ({ cols = 'grid-cols-2 sm:grid-cols-4', children }) => (
        <div className={`grid ${cols} border-t border-l border-white/[0.08]`}>{children}</div>
    );
    // 依指標數挑欄數：桌面選能整除的欄數（每列排滿、不留空格），手機一律 2 欄（3 個時 3 欄）
    const ledgerCols = (n) => n <= 2 ? 'grid-cols-2'
        : n === 3 ? 'grid-cols-3'
        : n % 5 === 0 ? 'grid-cols-2 sm:grid-cols-5'          // 5、10
        : n % 4 === 0 ? 'grid-cols-2 sm:grid-cols-4'          // 4、8、12
        : n % 6 === 0 ? 'grid-cols-2 sm:grid-cols-3 lg:grid-cols-6'
        : n % 3 === 0 ? 'grid-cols-2 sm:grid-cols-3'          // 9
        : 'grid-cols-2 sm:grid-cols-4';

    // columns: [{ key, label, en, align:'left'|'right', render(row), sortValue(row), cellClass(row) }]
    const DataTable = ({ columns, rows, initialSort = null, rowKey = (r, i) => i, caption }) => {
        const [sort, setSort] = React.useState(initialSort);   // { key, dir: 'asc'|'desc' }
        const colOf = (k) => columns.find(c => c.key === k);
        const sorted = React.useMemo(() => {
            if (!sort) return rows;
            const c = colOf(sort.key); if (!c) return rows;
            const get = c.sortValue || (r => r[c.key]);
            const sign = sort.dir === 'asc' ? 1 : -1;
            return rows.slice().sort((a, b) => {
                const x = get(a), y = get(b);
                if (isBlank(x) && isBlank(y)) return 0;
                if (isBlank(x)) return 1;            // 無資料一律排最後
                if (isBlank(y)) return -1;
                return (typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y))) * sign;
            });
        }, [rows, sort]);
        const toggle = (k) => setSort(s => (s && s.key === k)
            ? { key: k, dir: s.dir === 'desc' ? 'asc' : 'desc' }
            : { key: k, dir: colOf(k).align === 'left' ? 'asc' : 'desc' });
        return (
            <div className="overflow-x-auto border-t border-white/[0.08]">
                <table className="w-full text-sm border-collapse">
                    {caption && <caption className="sr-only">{caption}</caption>}
                    <thead>
                        <tr className="border-b border-white/15">
                            {columns.map((c, ci) => {
                                const active = sort && sort.key === c.key;
                                return (
                                    <th key={c.key} scope="col"
                                        aria-sort={active ? (sort.dir === 'asc' ? 'ascending' : 'descending') : 'none'}
                                        className={`px-3 py-2 font-normal whitespace-nowrap align-bottom ${c.align === 'left' ? 'text-left' : 'text-right'} ${ci === 0 ? 'max-sm:sticky max-sm:left-0 max-sm:z-[1] max-sm:bg-[#0A1626]' : ''}`}>
                                        <button onClick={() => toggle(c.key)}
                                            className={`inline-flex flex-col ${c.align === 'left' ? 'items-start' : 'items-end'} gap-0.5 hover:text-slate-100 ${active ? 'text-slate-100' : 'text-slate-400'}`}>
                                            <span className="text-[11px]">{c.label}{active && <span className="ml-1 text-[#12A150]">{sort.dir === 'asc' ? '↑' : '↓'}</span>}</span>
                                            {c.en && <span className="font-mono text-[10px] text-slate-500">{c.en}</span>}
                                        </button>
                                    </th>
                                );
                            })}
                        </tr>
                    </thead>
                    <tbody>
                        {sorted.map((r, i) => (
                            <tr key={rowKey(r, i)} className="border-b border-white/[0.06] odd:bg-white/[0.015] hover:bg-white/[0.04]">
                                {columns.map((c, ci) => (
                                    <td key={c.key}
                                        className={`px-3 py-2 whitespace-nowrap ${c.align === 'left' ? 'text-left text-slate-200' : 'text-right font-mono tabular-nums text-slate-200'} ${ci === 0 ? 'max-sm:sticky max-sm:left-0 max-sm:bg-[#0A1626] max-sm:whitespace-normal max-sm:min-w-[7.5rem] max-sm:max-w-[9.5rem] max-sm:text-[13px] max-sm:leading-snug' : ''} ${c.cellClass ? c.cellClass(r) : ''}`}>
                                        {c.render ? c.render(r) : (isBlank(r[c.key]) ? '—' : r[c.key])}
                                    </td>
                                ))}
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        );
    };

    return { splitTitle, pctColor, Delta, PctBar, StatCell, Ledger, ledgerCols, DataTable };
})();


// ---------- constants.js ----------
// 全域常數
window.PlayTypesList = ["Transition", "Isolation", "PRBallHandler", "PRRollMan", "Postup", "Spotup", "Handoff", "Cut", "OffScreen", "OffRebound", "Misc"];
window.CURRENT_SEASON = "2025-26"; // 投籃熱圖 doc id 用，需與 scripts/fetch_data.py 的 SEASON 一致

// 名稱比對用 key：去句點/重音/多餘空白後小寫。
// 必要性：同一人的名字在不同季的 API 回傳不一致
// （2025-26 是 "Terrence Shannon Jr."，2026-27 是 "Terrence Shannon Jr"），
// 而球員資料以 playerName 為主鍵，不正規化就會對不上。
window.nameKey = (n) => String(n || '')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')   // 去重音: Jokic
    .replace(/[.\u2019']/g, '')                            // 去句點與彎/直撇號
    .replace(/\s+/g, ' ').trim().toLowerCase();

// 賽季階段判斷（前端版本，對應 fetch_data.py 的 get_season_type()）
// 使用美東時間 UTC-5（不處理 DST，誤差可忍）
window.getSeasonPhase = function (date) {
    const d = date || new Date();
    const eastTime = new Date(d.getTime() - 5 * 3600 * 1000);
    const m = eastTime.getUTCMonth() + 1;
    const day = eastTime.getUTCDate();
    if ((m === 10 && day >= 20) || m === 11 || m === 12 || m === 1 || m === 2 || m === 3 || (m === 4 && day <= 15)) {
        return { type: 'regular', label: '例行賽', inSeason: true };
    } else if ((m === 4 && day >= 16) || m === 5 || (m === 6 && day <= 20)) {
        return { type: 'playoffs', label: '季後賽', inSeason: true };
    } else {
        return { type: null, label: '休賽期', inSeason: false };
    }
};
// 賽季選擇器選項：current = 當季每日快照，其餘為歷史終點快照。
// 單一來源：App.js 的跨季比較清單也讀 HISTORY_SEASON_OPTIONS，勿另建第二份。
// 不變式：option.key === Firestore 的 history docId（`${season}_${type}`）
window.HISTORY_SEASONS = ['2025-26', '2024-25', '2023-24', '2022-23'];
window.HISTORY_SEASON_OPTIONS = window.HISTORY_SEASONS.flatMap(s =>
    [['playoffs', '季後賽', '季'], ['regular', '例行賽', '例']].map(([t, l, sh]) => ({
        key: `${s}_${t}`, season: s, type: t,
        label: `${s} ${l}`, short: `${s.slice(2)}${sh}`,
        order: parseInt(s.slice(0, 4), 10) * 10 + (t === 'playoffs' ? 1 : 0),  // ComparisonTab 折線 X 軸排序用
    }))
);
window.SEASON_OPTIONS = [
    // 休賽期時該季已經打完，寫「進行中」是錯的（getSeasonPhase 必須定義在本行之前）
    {
        key: 'current', isCurrent: true,
        label: `${window.CURRENT_SEASON} ${window.getSeasonPhase().inSeason ? '進行中' : '最終'}`,
    },
    ...window.HISTORY_SEASON_OPTIONS,
];

// 新援探測順序：找該球員最近一個「真的有資料」的賽季。
// 只列這兩季，因為回補計畫只重跑 2025-26 / 2024-25；2023-24 與 2022-23 不重跑，
// 新援永遠不會出現在那兩季。（回補尚未執行前，這四個 doc 也還沒有新援）
window.HISTORY_PROBE_ORDER = ['2025-26_regular', '2025-26_playoffs', '2024-25_regular', '2024-25_playoffs'];

// 2026-27 名冊（來自 commonteamroster 實測）。一律寫無句點形式，比對走 nameKey。
// 用途只有一個：列出「在名冊上但當季快照還沒有數據」的球員（新援 / 尚未出賽者）。
// 刻意不拿來做排序權重——側欄排序改由快照的 MIN 決定（見 App.js availablePlayers），
// 這樣看哪一季就是那一季的輪換順序，交易後也不用改程式。
window.CURRENT_ROSTER_NAMES = [
    "Anthony Edwards", "LaMelo Ball", "Jaden McDaniels", "Jonathan Kuminga", "Rudy Gobert",
    "Donte DiVincenzo", "Terrence Shannon Jr", "Ayo Dosunmu", "Trey Lyles", "Cody Williams",
    "Bones Hyland", "Jaylen Clark", "Joan Beringer", "Enrique Freeman", "Isaiah Evans",
    "Trey Kaufman-Renn", "Zyon Pullin", "Rocco Zikarsky",
];

// 球隊標示：非灰狼才標。留隊球員回空字串 → 現有畫面完全不變
window.TEAM_ABBR = 'MIN';
window.teamTag = (abbr) => (!abbr || abbr === window.TEAM_ABBR) ? '' : `@${abbr}`;
window.NA_REASON = {
    CROSS_TEAM: '跨隊資料不適用：NBA API 的最近防守者（Defense Dashboard）/ On-Off 需綁定 TeamID，該季此球員不在灰狼，無法取得',
};
window.NA_BADGE = '跨隊不適用';

// teamAbbr 只有在 isNewcomer 時才可信。
// 理由：backfill_history.py 只對新援逐人查生涯分隊（Step 5b）；其餘球員的 teamAbbr
// 直接來自 leaguedashplayerstats 的 TEAM_ABBREVIATION，那個欄位只標「最後一隊」，
// 歷史賽季中途被交易走的灰狼球員會帶著別隊縮寫 → 無條件顯示會標錯人。
window.tagOfMeta = (meta) => (meta && meta.isNewcomer) ? window.teamTag(meta.teamAbbr) : '';

// normalizeHistoryPlayer 會把這些 metadata 注入每個類別 dict，
// 因此「這個類別有沒有真資料」不能用 Object.keys().length，必須排除掉它們
window.PLAYER_META_KEYS = ['playerId', 'isCurrentRoster', 'teamAbbr'];
window.hasRealData = (obj) => !!obj && Object.keys(obj).some(k => !window.PLAYER_META_KEYS.includes(k));

// 歷史快照的 localStorage 快取。
// 版本號：後端 backfill 改變結構時必須 +1，否則使用者瀏覽器會永遠讀到舊資料
// （舊版程式只要 cache 存在就 return，不再打 Firestore）。
// 不只「結構」變更要 +1，**每次重跑 backfill_history.py 也要 +1**：
// 快取只以 docId 為 key，內容變了（例如回補後多出新援）而版本沒動，
// 已開過頁面的使用者在 TTL 內完全看不到新資料。
window.HISTORY_CACHE_VER = 4;                 // v4 = 2025-26 / 2024-25 回補納入新援
window.HISTORY_CACHE_TTL = 24 * 3600 * 1000;
const _histKey = (docId) => `wt_history_v${window.HISTORY_CACHE_VER}_${docId}`;
window.purgeHistoryCache = (all) => {
    try {
        Object.keys(localStorage).forEach(k => {
            if (k.startsWith('wt_history_') && (all || !k.startsWith(`wt_history_v${window.HISTORY_CACHE_VER}_`)))
                localStorage.removeItem(k);
        });
    } catch (e) { /* private mode / quota */ }
};
window.readHistoryCache = (docId) => {
    try {
        const o = JSON.parse(localStorage.getItem(_histKey(docId)) || 'null');
        if (!o || o.v !== window.HISTORY_CACHE_VER) return null;
        if (Date.now() - o.t > window.HISTORY_CACHE_TTL) return null;
        return o.d;
    } catch (e) { return null; }
};
window.writeHistoryCache = (docId, d) => {
    try { localStorage.setItem(_histKey(docId), JSON.stringify({ v: window.HISTORY_CACHE_VER, t: Date.now(), d })); }
    catch (e) { window.purgeHistoryCache(true); }   // quota 滿 → 清掉全部歷史快取
};
window.purgeHistoryCache(false);   // 載入時立即清掉舊版 key

// 每日快照的訂閱起始日：doc id 就是日期字串，故以 doc id 範圍過濾出「當季」。
// 為什麼不用 orderBy(documentId(),'desc') + limit：那需要建 Firestore 複合索引，
// 而 onSnapshot 沒有 error callback，缺索引時會「靜默失敗」讓整個面板空掉。
